fn cell(value: &Value) -> String {
    match value {
        Value::String(text) => text.as_str().to_string(),
        Value::Null => "null".to_string(),
        Value::Int64(number) => number.to_string(),
        Value::Bool(flag) => flag.to_string(),
        Value::RdfTerm(term) => {
            let text = term.to_ntriples();
            match text.strip_prefix('<') {
                Some(iri) => iri.trim_end_matches('>').to_string(),
                None => text.split('"').nth(1).unwrap_or("").to_string(),
            }
        }
        other => format!("{other:?}"),
    }
}

fn rows_of(session: &Session, query: &str) -> Vec<String> {
    let result = session
        .execute_sparql(query)
        .unwrap_or_else(|error| panic!("{query}: {error}"));
    let mut rows: Vec<String> = result
        .rows()
        .iter()
        .map(|row| row.iter().map(cell).collect::<Vec<_>>().join("|"))
        .collect();
    rows.sort();
    rows
}

fn plan_of(session: &Session, query: &str) -> String {
    session
        .execute_sparql(&format!("EXPLAIN {query}"))
        .unwrap_or_else(|error| panic!("EXPLAIN {query}: {error}"))
        .rows()
        .iter()
        .map(|row| cell(&row[0]))
        .collect::<Vec<_>>()
        .join("\n")
}

fn database() -> GrafeoDB {
    let db = GrafeoDB::new_in_memory();
    let session = db.session();
    for statement in DATA {
        session.execute_sparql(statement).unwrap();
    }
    db
}

/// Every case answers as the SPARQL text does (rdflib's rows).
#[test]
fn every_case_answers_as_the_text() {
    let db = database();
    let session = db.session();
    let mut wrong = Vec::new();
    for case in CASES {
        let found = rows_of(&session, case.query);
        if found != case.rows {
            wrong.push(format!("{}: {found:?}\n  want {:?}", case.name, case.rows));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// Every case's plan shows what the design states for it.
#[test]
fn every_case_has_its_plan() {
    let db = database();
    let session = db.session();
    let mut wrong = Vec::new();
    for case in CASES {
        let plan = plan_of(&session, case.query);
        // The scope's hidden check prints `SAMETERM`, a user's filter `sameTerm`: both count.
        let same_term = plan.to_lowercase().contains("sameterm(");
        let fault = match &case.plan {
            Plan::ScanConstraint => {
                (plan.contains("Bind (") || same_term).then_some("a Bind or a sameTerm filter left")
            }
            Plan::JoinKeyed => same_term.then_some("a sameTerm filter left"),
            Plan::FilterStays => (!same_term).then_some("the sameTerm filter gone"),
            Plan::EqStays => (!plan.contains(" Eq ")).then_some("the = filter gone"),
            Plan::Unchanged(today) => (plan != *today).then_some("the plan changed"),
            Plan::RowsOnly => None,
        };
        if let Some(fault) = fault {
            wrong.push(format!("{}: {fault}\n{plan}", case.name));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n\n"));
}
